// PreToolUse guard that Claude Code and Codex call through
// "task -x hook:guard". It reads one tool call as JSON on stdin, matches it
// against the rules in the policy file named by its only argument, and
// denies by exiting 2 with the reason on stderr. Anything else exits 0.
//
// The repository may add a policy.local.json next to the policy file: extra
// deny rules, and exceptions that each lift one rule for the commands or
// paths a pattern matches in full. A local file the guard cannot use
// blocks every call. See docs/specs/0050-guard-exceptions.md.
//
// Generated by VibeConform (prod-ts/v1, ts-repo-tooling). The Go and Python
// guards in prod-go and prod-py implement the same contract; a shared test
// corpus keeps the three in agreement. See
// docs/specs/0021-agent-hooks-task-interface.md in the VibeConform
// repository.
//
// Node standard library only, so it runs without anything installed.
import { existsSync, readFileSync } from 'node:fs'
import path from 'node:path'

// The exit code both agents read as "block this tool call".
const EXIT_DENY = 2

function deny(message) {
  process.stderr.write(`${message}\n`)
  process.exit(EXIT_DENY)
}

function loadPolicy(path) {
  let policy
  try {
    policy = JSON.parse(readFileSync(path, 'utf8'))
  } catch (err) {
    throw new Error(`reading policy ${path}: ${err.message}`, { cause: err })
  }
  if (policy.version !== 1) {
    throw new Error(
      `policy ${path} has version ${policy.version}; this guard understands version 1`,
    )
  }
  return policy
}

// The repository's own policy file, next to the managed one.
const LOCAL_NAME = 'policy.local.json'

function objects(local, key) {
  if (!(key in local)) {
    return []
  }
  const list = local[key]
  if (
    !Array.isArray(list) ||
    list.some((o) => o === null || typeof o !== 'object' || Array.isArray(o))
  ) {
    throw new Error(`${key} is not a list of objects`)
  }
  return list
}

function nonEmpty(v) {
  return typeof v === 'string' && v !== ''
}

// Adds the rules and exceptions of the local file at file to policy. An
// absent file adds nothing; any other problem throws.
function addLocal(policy, file) {
  if (!existsSync(file)) {
    return
  }
  let local
  try {
    local = JSON.parse(readFileSync(file, 'utf8'))
  } catch {
    throw new Error('not a JSON object')
  }
  if (local === null || typeof local !== 'object' || Array.isArray(local)) {
    throw new Error('not a JSON object')
  }
  for (const key of Object.keys(local)) {
    if (!['version', 'rules', 'exceptions'].includes(key)) {
      throw new Error(`unknown key "${key}"; only version, rules and exceptions are allowed`)
    }
  }
  if (local.version !== 1) {
    throw new Error('version is not 1, the only version this guard understands')
  }
  objects(local, 'rules').forEach((r, i) => {
    for (const key of ['id', 'field', 'pattern', 'message']) {
      if (!nonEmpty(r[key])) {
        throw new Error(`rule ${i + 1} has no ${key}`)
      }
    }
    if (!Object.hasOwn(policy.tools, r.field)) {
      throw new Error(`rule ${r.id} has field "${r.field}", which the policy does not know`)
    }
    const raw = nonEmpty(r.raw) ? r.raw : r.pattern
    policy.rules.push({ id: r.id, field: r.field, pattern: r.pattern, raw, message: r.message })
  })
  objects(local, 'exceptions').forEach((e, i) => {
    if (!nonEmpty(e.rule) || !nonEmpty(e.pattern)) {
      throw new Error(`exception ${i + 1} needs a rule and a pattern`)
    }
    policy.exceptions.push({ rule: e.rule, pattern: e.pattern })
  })
}

// Whether an exception lifts rule for value. A pattern that does not
// compile lifts nothing.
function excepted(policy, rule, value) {
  return policy.exceptions.some((e) => {
    if (e.rule !== rule.id) {
      return false
    }
    try {
      return new RegExp(`^(?:${e.pattern})$`).test(value)
    } catch {
      return false
    }
  })
}

// A pattern that does not compile counts as a match: a broken rule must
// block rather than quietly stop guarding.
function matches(pattern, s) {
  try {
    return new RegExp(pattern).test(s)
  } catch {
    return true
  }
}

function fieldFor(policy, toolName) {
  for (const [field, tools] of Object.entries(policy.tools)) {
    if (tools.includes(toolName)) {
      return field
    }
  }
  return undefined
}

// Returns the message of the first rule the tool call matches, or
// undefined. The parsed field is matched when the payload parses, names a
// known tool, and carries that tool's field as a string. Otherwise every
// rule's raw pattern is matched against the payload text, which is what the
// bash hooks did before this guard replaced them: never less strict.
// Exceptions apply to the parsed field only.
function check(policy, stdin) {
  let call
  try {
    call = JSON.parse(stdin)
  } catch {
    call = undefined
  }
  if (call !== null && typeof call === 'object') {
    const field = fieldFor(policy, call.tool_name)
    const value = call.tool_input?.[field]
    if (field !== undefined && typeof value === 'string') {
      const rule = policy.rules.find(
        (r) => r.field === field && matches(r.pattern, value) && !excepted(policy, r, value),
      )
      return rule?.message
    }
  }
  return policy.rules.find((r) => matches(r.raw, stdin))?.message
}

function main() {
  if (process.argv.length !== 3) {
    deny('guard: usage: guard <policy.json>; blocking until the hook:guard task is fixed')
  }

  let policy
  try {
    policy = loadPolicy(process.argv[2])
  } catch (err) {
    // Fail closed: a guard that cannot read its policy cannot tell a
    // destructive command from a safe one.
    deny(`guard: ${err.message}; blocking until the policy file is fixed`)
  }
  policy.exceptions = []
  const local = path.join(path.dirname(process.argv[2]), LOCAL_NAME)
  try {
    addLocal(policy, local)
  } catch (err) {
    // Fail closed here too: ignoring the file would drop its rules.
    deny(
      `guard: ${local.split(path.sep).join('/')}: ${err.message}; every tool call is blocked until it is fixed. ` +
        'Ask the user to fix it (in Claude Code: ! <command>, or their editor).',
    )
  }

  let stdin = ''
  try {
    stdin = readFileSync(0, 'utf8')
  } catch (err) {
    // An empty or closed stdin is an ordinary empty payload, not an error.
    if (err.code !== 'EOF') {
      deny(`guard: reading stdin: ${err.message}`)
    }
  }

  const message = check(policy, stdin)
  if (message !== undefined) {
    deny(message)
  }
}

main()
